import {$,esc,fmtDate,safeURL} from './app.js';
import {normalizeSearch} from './rules.js';
export function sourceDialog({manifest:m,cities,registry}){
 $('#sources-content').innerHTML=`<p><strong>${m.totalRecords.toLocaleString('fi-FI')} lähdekohdetta · ${m.coveredMunicipalities} kunnassa / ${m.totalMunicipalities}.</strong><br>Tämä ei ole osuus kaikista Suomen pysäköintipaikoista. Kohde tarkoittaa aluetta tai katuosuutta. Lähteissä voi olla päällekkäisyyksiä.</p><p class="caution">Kattavuus on osittainen. Erityisesti kadunvarsipaikkoja ja puuttuvilla maksu- tai aikamerkinnöillä olevia kohteita jää pois. Lähdeotos koottu ${fmtDate(m.generatedAt)}. Paikkoja ei ole tarkistettu maastossa.</p><h3>Mistä tiedot tulevat?</h3>${registry.filter(s=>s.role==='data').map(s=>`<p><a href="${safeURL(s.url)}" target="_blank" rel="noopener noreferrer"><strong>${esc(s.title)}</strong></a> · ${m.sources[s.id]?.records?.toLocaleString('fi-FI')??0} kohdetta<br>${esc(s.coverage)}<br><small>${esc(s.license)} · haettu ${fmtDate(m.sources[s.id]?.fetchedAt)} · <a href="data/${s.id}.json" download>Lataa lähdeaineiston muunnos</a></small></p>`).join('')}<h3>Mitä ”ilmainen nyt” tarkoittaa?</h3><p>Tila lasketaan lähteen ehdoista Suomen ajassa. Se ei ole pysäköintilupa, vapaiden ruutujen mittaus eikä tieto paikan päällä olevasta tilapäisestä kiellosta. Epäselvät ehdot, puuttuva aukioloaika, ristiriita tai yli 30 päivää vanha nouto tuottavat tilan ”Tarkista ehdot”. Yli vuoden vanha OSM-muokkaus tai tarkistusmerkintä ei pääse aktiivisten joukkoon.</p><p>24/7-suodatin edellyttää ympärivuorokautista aukioloa ja maksuttomuutta. Aikaraja voi silti koskea yhtä pysäköintiä. Pyhäpäivät huomioidaan kaupunkiaineiston päiväsäännöissä; monimutkaisia OSM-ehtoja ei arvata.</p><h3>Vuoden 2026 lähdetarkistukset</h3>${registry.filter(s=>s.role==='research').map(s=>`<p><a href="${safeURL(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)}</a><br>${esc(s.coverage)}</p>`).join('')}<h3>Kuntakohtainen kattavuus</h3><label for="coverage-search">Hae kuntaa</label><input id="coverage-search" placeholder="Kunnan nimi" style="display:block;width:100%;padding:12px;margin:8px 0;border:1px solid #b6c7bf;border-radius:7px"><div style="overflow:auto;max-height:320px"><table><thead><tr><th>Kunta</th><th>Viranom.</th><th>OSM</th><th>Tila</th></tr></thead><tbody id="coverage-table"></tbody></table></div><h3>Lisenssit ja tietosuoja</h3><p>Helsingin kaupunki sekä Fintraffic / Digitraffic: <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener noreferrer">CC BY 4.0</a>. OpenStreetMap ja sen tekijät: <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener noreferrer">ODbL</a>. Kuntarajat: Tilastokeskus, CC BY 4.0. Aineistot on suodatettu, sijainteja muunnettu karttapisteiksi ja sääntöjä normalisoitu. OSM-johdannainen tietokanta on erikseen ladattavissa ODbL-lisenssillä.</p><p>Sijaintia kysytään vain Lähelläni-painikkeesta; sitä ei tallenneta. Karttatiilet ladataan OpenStreetMapilta. Osoitehaku lähettää kirjoitetun haun Nominatim-palveluun vain Hae-painikkeesta. Ei analytiikkaa eikä käyttäjätiliä. Reittiohjeen avaaminen välittää kohteen Google Mapsiin.</p><p>Tiedot ovat tallennettu lähdeotos. Kellonajan mukainen tila päivittyy minuutin välein, mutta lähteiden muutoksia ei haeta automaattisesti. Päivitysohje ja lähdekartoitus sisältyvät sovelluksen toimitukseen.</p>`;
 function rows(q=''){const v=normalizeSearch(q);$('#coverage-table').innerHTML=cities.filter(c=>normalizeSearch(c.name).includes(v)||normalizeSearch(c.nameSv).includes(v)).sort((a,b)=>a.name.localeCompare(b.name,'fi')).map(c=>`<tr><td>${esc(c.name)}</td><td>${(c.counts.helsinki||0)+(c.counts.liipi||0)}</td><td>${c.counts.osm||0}</td><td>${Object.values(c.counts).some(Boolean)?'Osittainen':'Ei kohteita'}</td></tr>`).join('');}rows();$('#coverage-search').oninput=e=>rows(e.target.value);$('#sources-dialog').showModal();
}
